# Dynamic Tag Generator - runnable demo (JAH-ATK172-000001)
import math, re
from collections import Counter
RANK = 1
SIG = False
DOCS = ['The telescope observed distant stars and planets all night.', 'Bake the flour with sugar in a hot oven until golden.']
toks = [[w for w in re.findall(r"[a-z]+", d.lower()) if len(w) > 3] for d in DOCS]
df = Counter()
for t in toks: df.update(set(t))
STOP = {"this", "that", "with", "from", "have", "were", "will", "their", "about"}
for i, t in enumerate(toks):
    tf = Counter(t); n = len(t)
    scores = {w: (c/n) * math.log(len(DOCS)/df[w]) for w, c in tf.items() if w not in STOP}
    tags = sorted(scores, key=scores.get, reverse=True)[:4]
    print("doc%d tags: %s" % (i+1, tags))
    if RANK >= 2:
        print("   scores:", {w: round(scores[w], 3) for w in tags})
if RANK >= 3:
    print("vocabulary size:", len(df))
if SIG:
    print("Signature lineage stamp: JAH-SIG-TAG-" + "JAH-ATK172-000001")
print("record:", "JAH-ATK172-000001", "OK")

